CREATE TABLE IF NOT EXISTS richo_release_artifacts(id uuid PRIMARY KEY,version text NOT NULL,commit_sha text NOT NULL,digest text NOT NULL UNIQUE,build_id text,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,immutable boolean NOT NULL DEFAULT true,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_deployment_manifests(id uuid PRIMARY KEY,artifact_id uuid NOT NULL REFERENCES richo_release_artifacts(id),environment text NOT NULL,migrations jsonb NOT NULL DEFAULT '[]'::jsonb,config_digest text,dependencies jsonb NOT NULL DEFAULT '{}'::jsonb,strategy text NOT NULL,status text NOT NULL DEFAULT 'planned',correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_deployments(id uuid PRIMARY KEY,manifest_id uuid NOT NULL REFERENCES richo_deployment_manifests(id),environment text NOT NULL,strategy text NOT NULL,status text NOT NULL,started_at timestamptz,completed_at timestamptz,release_evidence jsonb NOT NULL DEFAULT '{}'::jsonb,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_rollback_points(id uuid PRIMARY KEY,deployment_id uuid NOT NULL REFERENCES richo_deployments(id),artifact_id uuid REFERENCES richo_release_artifacts(id),config_digest text,database_checkpoint text,verified boolean NOT NULL DEFAULT false,correlation_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_environment_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),environment text NOT NULL,config jsonb NOT NULL,config_digest text NOT NULL,captured_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_deployment_env_idx ON richo_deployments(environment,created_at DESC);
